CREATE TABLE products (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE parties (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('supplier','retailer')), phone TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE purchases (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_id BIGINT NOT NULL REFERENCES parties(id), product_id BIGINT NOT NULL REFERENCES products(id), boxes INTEGER NOT NULL CHECK(boxes>0), unit_cost NUMERIC(18,2) NOT NULL CHECK(unit_cost>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE batches (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, purchase_id BIGINT NOT NULL UNIQUE REFERENCES purchases(id), product_id BIGINT NOT NULL REFERENCES products(id), remaining INTEGER NOT NULL CHECK(remaining>=0), unit_cost NUMERIC(18,2) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE sales (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, retailer_id BIGINT NOT NULL REFERENCES parties(id), total NUMERIC(18,2) NOT NULL CHECK(total>=0), request_key TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sale_lines (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, sale_id BIGINT NOT NULL REFERENCES sales(id), product_id BIGINT NOT NULL REFERENCES products(id), boxes INTEGER NOT NULL CHECK(boxes>0), unit_price NUMERIC(18,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE sale_allocations (sale_line_id BIGINT NOT NULL REFERENCES sale_lines(id), batch_id BIGINT NOT NULL REFERENCES batches(id), boxes INTEGER NOT NULL CHECK(boxes>0), unit_cost NUMERIC(18,2) NOT NULL, PRIMARY KEY(sale_line_id,batch_id));
CREATE TABLE receipts (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, retailer_id BIGINT NOT NULL REFERENCES parties(id), amount NUMERIC(18,2) NOT NULL CHECK(amount>0), method TEXT NOT NULL CHECK(method IN ('cash','upi')), request_key TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
